class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        # 1 MiB = 1024 * 1024 bytes = 1,048,576 bytes
        self.limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Maps month -> {filename: size_bytes}
        self._history: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("Upload size must be greater than 0.")

        month_data = self._history.setdefault(month, {})

        # Requirement 1: Uploading a file with the same name in the same month
        # does not count towards the limit a second time.
        if name in month_data:
            return

        current_used = sum(month_data.values())
        # Requirement 3: Exceeding the monthly limit raises ValueError and is not counted.
        if current_used + size_bytes > self.limit_bytes:
            raise ValueError("Upload exceeds the monthly quota limit.")

        month_data[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        """Requirement 2: Deleting a file does not give back quota in the current month."""
        # Deleting does not reduce used quota, so we do not remove the recorded size
        # from quota calculations.

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._history.get(month, {}).values())
```

